  /** DataQualityScan related setting. */
  dataQualitySpec?: DataScan_DataQualitySpec | Computed<DataScan_DataQualitySpec>;
  /** Optional. Description of the scan. Must be between 1-1024 characters. */
  description?: string | Computed<string>;
  /** Optional. User friendly display name. Must be between 1-256 characters. */
  displayName?: string | Computed<string>;
  /** The identity to run the datascan. */
  executionIdentity?: DataScan_ExecutionIdentity | Computed<DataScan_ExecutionIdentity>;
  /** DataScan execution settings. */
  executionSpec?: DataScan_ExecutionSpec | Computed<DataScan_ExecutionSpec>;
  /** Status of the data scan execution. */
